import ij.*;import ij.io.*;import ij.gui.*;import ij.process.*;import ij.measure.*;import java.nio.file.*;import java.util.*;import java.util.zip.*;
public class ReviewCorrectedMultiplex {
 static void check(boolean a,String m){if(!a)throw new AssertionError(m);}
 static void cal(Calibration a,Calibration b){check(a.pixelWidth==b.pixelWidth&&a.pixelHeight==b.pixelHeight&&a.pixelDepth==b.pixelDepth&&a.frameInterval==b.frameInterval&&a.getUnit().equals(b.getUnit()),"Calibration mismatch");}
 public static void main(String[] args)throws Exception{for(String arg:args){Path p=Path.of(arg);ImagePlus out=IJ.openImage(p.resolve("output/Results/Aligned_Stack.tif").toString()),ref=IJ.openImage(p.resolve("inputs/Layer1_Hu.tif").toString()),qc=IJ.openImage(p.resolve("output/Results/hu_stack.tif").toString());check(Arrays.equals(out.getDimensions(),new int[]{256,256,7,1,1}),"dims");cal(ref.getCalibration(),out.getCalibration());cal(ref.getCalibration(),qc.getCalibration());System.out.println(p.getFileName()+" calibration PASS "+out.getCalibration().pixelWidth+","+out.getCalibration().pixelHeight+","+out.getCalibration().frameInterval+","+out.getCalibration().getUnit());for(int s=1;s<=7;s++){String name=out.getStack().getSliceLabel(s);ImagePlus in=IJ.openImage(p.resolve("inputs").resolve(name).toString());byte[] a=(byte[])in.getProcessor().getPixels(),b=(byte[])out.getStack().getProcessor(s).getPixels();int round=name.charAt(5)-'0';if(round==1){check(Arrays.equals(a,b),"R1 changed");System.out.println(name+" exact_R1=true");}else{int dx=round==2?7:-6,dy=round==2?-5:8;double before=0,after=0;long n=0;for(int y=24;y<232;y++)for(int x=24;x<232;x++){int expected=a[(y+dy)*256+x+dx]&255,d0=(a[y*256+x]&255)-expected,d1=(b[y*256+x]&255)-expected;before+=d0*d0;after+=d1*d1;n++;}before/=n;after/=n;check(before>100&&after<before*.15,"Uncorrected transform");if(p.getFileName().toString().equals("full-sift"))check(after==0,"SIFT should be exact in this fixture");System.out.println(name+" before_mse="+before+" after_mse="+after+" reduction="+(1-after/before));}}
 for(int k=1;k<=3;k++){ImagePlus in=IJ.openImage(p.resolve("inputs/Layer"+k+"_Hu.tif").toString());check(Arrays.equals((byte[])in.getProcessor().getPixels(),(byte[])qc.getStack().getProcessor(k).getPixels()),"QC changed");}
 try(ZipFile z=new ZipFile(p.resolve("output/Results/landmark_correspondences.zip").toFile())){check(z.size()==4,"ROI entries");for(int k=1;k<=2;k++){FloatPolygon[] f=new FloatPolygon[2];for(int i=0;i<2;i++){String n="hu_"+k+(i==0?"_ref.roi":"_target.roi");Roi r=new RoiDecoder(z.getInputStream(z.getEntry(n)).readAllBytes(),n).getRoi();check(r instanceof PointRoi,"ROI type");f[i]=r.getFloatPolygon();}check(f[0].npoints>=7&&f[0].npoints==f[1].npoints,"ROI counts");double error=0,dx=0,dy=0;int ex=k==1?7:-6,ey=k==1?-5:8;for(int i=0;i<f[0].npoints;i++){double x=f[1].xpoints[i]-f[0].xpoints[i],y=f[1].ypoints[i]-f[0].ypoints[i];dx+=x;dy+=y;error+=Math.hypot(x-ex,y-ey);}error/=f[0].npoints;check(error<1,"ROI displacement");System.out.println("pair="+k+" points="+f[0].npoints+" mean_dx="+dx/f[0].npoints+" mean_dy="+dy/f[0].npoints+" mean_error="+error);}}
 System.out.println(p.getFileName()+" independent_saved_output_PASS");}}
}
